INSERT questionnaire.ClientSections(TemplateVersion,SectionId,Position,Title,Repeatable,DefinitionJson) VALUES
('client-v1',N'company',1,N'Company and assessment scope',0,N'{"groupFields":[],"help":"Answer for the company and assessment scope.","description":""}'),
('client-v1',N'assets',2,N'Asset inventory and ownership',1,N'{"groupFields":[{"id":"assetClass","label":"Asset class","type":"select","required":true,"options":[{"id":"endpoints","label":"Endpoints"},{"id":"servers","label":"Servers"},{"id":"databases","label":"Databases"},{"id":"network-devices","label":"Network devices"},{"id":"cloud-workloads","label":"Cloud workloads"},{"id":"business-applications","label":"Business applications"},{"id":"saas-services","label":"SaaS services"}]},{"id":"management","label":"Management","type":"select","required":true,"options":[{"id":"managed","label":"Managed"},{"id":"unmanaged","label":"Unmanaged"}]}],"help":"Add groups for each asset class, environment and management boundary.","description":"Repeat AST-01 through AST-06 for endpoints, physical/virtual servers, databases, network devices,\ncloud workloads, business applications and SaaS services. Separate managed and unmanaged assets.\n\n\nSuggested evidence: inventory export, discovery summary, ownership and lifecycle records."}'),
('client-v1',N'backups',3,N'Backups and recovery',1,N'{"groupFields":[{"id":"assetClass","label":"Asset class","type":"select","required":true,"options":[{"id":"endpoints","label":"Endpoints"},{"id":"servers","label":"Servers"},{"id":"databases","label":"Databases"},{"id":"email-and-collaboration-saas","label":"Email and collaboration / SaaS"},{"id":"cloud-workloads-and-storage","label":"Cloud workloads and storage"},{"id":"network-and-security-configuration","label":"Network and security configuration"}]}],"help":"Add groups for endpoints, servers, databases, SaaS, cloud workloads and network configurations as applicable. Keep differing strategies separate.","description":"Create a separate backup group for each of these classes:\n\n\nRepeat by product, environment or criticality where strategies differ. Question IDs combine the\nbase ID and class, for example `BKP-01.END` and `BKP-01.DB`; each repeated group also has a stable\nscope ID. Avoid double-counting assets across groups in later reporting.\n\n\nIf BKP-01 is No, still establish actual protection and coverage: ad hoc backups may exist.\nIf coverage is zero, capture business impact and recovery alternatives. For databases, add:\n\n\nSuggested evidence: strategy, coverage/job summaries, retention settings, deletion protections,\nrestore-test results and recovery runbooks. A successful backup job does not prove restoration;\nsynchronization or replication alone must not be automatically accepted as recoverable backup."}'),
('client-v1',N'identity',4,N'Identity and access',1,N'{"groupFields":[{"id":"population","label":"Account population","type":"select","required":true,"options":[{"id":"administrators","label":"Administrators"},{"id":"ordinary-users","label":"Ordinary users"},{"id":"service-identities","label":"Service identities"}]}],"help":"Add separate groups for administrators and ordinary users in each identity environment.","description":"Repeat coverage questions for each identity environment and separately for administrators and\nordinary users. Distinguish policy configuration from actual enforcement and exceptions.\n\n\nSuggested evidence: scoped identity/policy summaries, access reviews and onboarding/offboarding records."}'),
('client-v1',N'devices',5,N'Endpoints, servers and vulnerability management',1,N'{"groupFields":[{"id":"assetClass","label":"Asset class","type":"select","required":true,"options":[{"id":"endpoints","label":"Endpoints"},{"id":"servers","label":"Servers"}]}],"help":"Add separate endpoint and server groups, including remote devices.","description":"Repeat relevant coverage questions separately for endpoints and servers, including remote devices.\n\n\nSuggested evidence: management/EDR health, encryption and patch summaries, vulnerability report and baseline."}'),
('client-v1',N'network',6,N'Network, remote access and configuration',0,N'{"groupFields":[],"help":"Answer for the company and assessment scope.","description":"Suggested evidence: redacted diagrams, exposure inventory, remote-access policy and rule/change reviews."}'),
('client-v1',N'cloud',7,N'Cloud, email and collaboration',1,N'{"groupFields":[{"id":"platform","label":"Platform / tenant","type":"text","required":true}],"help":"Add a group for each tenant or platform.","description":"Repeat by tenant/platform. Automated observations can supplement answers where supported.\n\n\nSuggested evidence: configuration summaries, sharing reviews, email protection/domain reports and logging settings."}'),
('client-v1',N'data',8,N'Data protection and privacy',0,N'{"groupFields":[],"help":"Answer for the company and assessment scope.","description":"Suggested evidence: data inventory, access/retention policies, control summaries and disposal records."}'),
('client-v1',N'response',9,N'Monitoring, incident response and continuity',0,N'{"groupFields":[],"help":"Answer for the company and assessment scope.","description":"Suggested evidence: alert coverage, escalation runbooks, redacted exercise results and continuity plans."}'),
('client-v1',N'governance',10,N'Governance, people and suppliers',0,N'{"groupFields":[],"help":"Answer for the company and assessment scope.","description":"Suggested evidence: policy register, training summary, supplier reviews, risk register and action plan."}'),
('client-v1',N'ai',11,N'AI agent and Copilot readiness',1,N'{"groupFields":[{"id":"product","label":"AI product / use case","type":"text","required":true}],"help":"Add a group for each proposed or deployed AI product/use case.","description":"Repeat for each proposed or deployed AI product/use case. Do not assume every Copilot product\nhas the same prerequisites or that licensing alone establishes readiness.\n\n\nSuggested evidence: use-case register, access review, permission inventory, product-specific readiness\nchecklist, pilot/test results and operating procedures. General findings require product-specific validation."}'),
('client-v1',N'profiles',12,N'Insurance and framework profile intake',0,N'{"groupFields":[],"help":"Answer for the company and assessment scope.","description":"These questions select the appropriate view and additional questionnaire. They do not establish\nthat this core catalog covers any insurer form, CMMC level or NIST publication in full.\n\n\nOnly publish detailed profile conclusions after the selected criteria and mappings have been\nreviewed. Framework scope and applicability require explicit review; generic security answers\nalone cannot establish compliance or certification."}');
